window.MODTESTS={"tefl-m1": [{"id": "tefl-m01-test-A", "model": "A", "items": [{"id": "tefl-m01-test-A:1", "type": "mc4", "q": "<div class=\"q-hard\">Which feature of English makes it comparatively easy for learners?</div><div class=\"q-simple\">Which feature makes English easier to learn?</div><div class=\"q-ar\">أي سمة في الإنجليزي بتخليها أسهل نسبيًا للمتعلمين؟</div>", "o": ["Marks on letters that show pronunciation", "A mostly fixed word order (SVO) and weak inflection", "Tones that change word meaning", "Spelling that always matches sound"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: English has almost no marks on letters.</div><div class=\"ex-ar\">غلط: الإنجليزي تقريبًا مفيهوش علامات على الحروف.</div>", "<div class=\"ex-en\">Right: SVO order and few word endings keep the system simple.</div><div class=\"ex-ar\">صح: ترتيب <span class=\"en\">SVO</span> وقلة نهايات الكلمات بيبسّطوا النظام.</div>", "<div class=\"ex-en\">Wrong: English is not tonal. Tones are a difficulty for tonal-language speakers.</div><div class=\"ex-ar\">غلط: الإنجليزي مش نغمي.</div>", "<div class=\"ex-en\">Wrong: sound and spelling often do not match. This is the biggest problem.</div><div class=\"ex-ar\">غلط: الإملاء والنطق غالبًا مش متطابقين.</div>"], "l": "tefl-01"}, {"id": "tefl-m01-test-A:2", "type": "msel", "q": "<div class=\"q-hard\">Which of the following are listed as hard parts of English for many learners? Tick all that apply.</div><div class=\"q-simple\">Which are hard for learners? Tick all that apply.</div><div class=\"q-ar\">أي مما يلي مذكور كأجزاء صعبة في الإنجليزي لكتير من المتعلمين؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["The articles a, an and the", "Sounds such as 'th'", "The fixed SVO word order", "Phrasal verbs"], "a": [0, 1, 3], "ex": ["<div class=\"ex-en\">Right: hard especially when the first language has none.</div><div class=\"ex-ar\">صح: صعبة خصوصًا لو اللغة الأولى مفيهاش أدوات.</div>", "<div class=\"ex-en\">Right: they need the tongue tip, which some languages never use.</div><div class=\"ex-ar\">صح: بتحتاج طرف اللسان وبعض اللغات مبتستخدمهوش.</div>", "<div class=\"ex-en\">Wrong: fixed order is a feature that makes English easier.</div><div class=\"ex-ar\">غلط: الترتيب الثابت بيسهّل الإنجليزي.</div>", "<div class=\"ex-en\">Right: they are very common in speech and can look like nonsense to a beginner.</div><div class=\"ex-ar\">صح: شائعة جدًا في الكلام وممكن تبان بلا معنى للمبتدئ.</div>"], "l": "tefl-01"}, {"id": "tefl-m01-test-A:3", "type": "mc3", "q": "<div class=\"q-hard\">Spanish is syllable-timed. What effect does this often have on Spanish learners' English?</div><div class=\"q-simple\">What happens to a Spanish student's English rhythm?</div><div class=\"q-ar\">الإسباني لغة مقطعية الزمن. إيه تأثير ده على إنجليزي المتعلم الإسباني؟</div>", "o": ["It has no effect on listeners", "It sounds too fast, because stress is added to every word", "It can sound flat and robotic, because every syllable gets equal time"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: native listeners can miss the important words.</div><div class=\"ex-ar\">غلط: السامع ممكن يفوّت الكلمات المهمة.</div>", "<div class=\"ex-en\">Wrong: the problem is lack of stress contrast, not extra stress.</div><div class=\"ex-ar\">غلط: المشكلة غياب التباين في النبر.</div>", "<div class=\"ex-en\">Right: English is stress-timed, so listeners miss the important words.</div><div class=\"ex-ar\">صح: الإنجليزي نبري، فالسامع بيفوّت الكلمات المهمة.</div>"], "l": "tefl-02"}, {"id": "tefl-m01-test-A:4", "type": "tf", "q": "<div class=\"q-hard\">The lesson says teachers should never use students' L1 in class.</div><div class=\"q-simple\">True or false: never use L1.</div><div class=\"q-ar\">الدرس بيقول إن المدرّس لازم ميستخدمش لغة الطلاب الأولى خالص.</div>", "o": ["True", "False"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: the lesson sees L1 as another classroom resource, used with good judgment.</div><div class=\"ex-ar\">غلط: الدرس بيشوف الـ <span class=\"en\">L1</span> مورد إضافي بيتستخدم بحُسن تقدير.</div>", "<div class=\"ex-en\">Right: there are seven practical reasons to use it, such as clarifying meaning and saving time.</div><div class=\"ex-ar\">صح: فيه سبع أسباب عملية لاستخدامه زي توضيح المعنى وتوفير الوقت.</div>"], "l": "tefl-03"}, {"id": "tefl-m01-test-A:5", "type": "mc4", "q": "<div class=\"q-hard\">A competent teacher is defined with the mnemonic KASH. Which option lists its four parts?</div><div class=\"q-simple\">What are the four parts of KASH?</div><div class=\"q-ar\">المدرّس الكفء بيتعرّف بالاختصار KASH. أي اختيار بيعدد أجزاءه الأربعة؟</div>", "o": ["Knowledge, Accuracy, Support, Hard work", "Knowledge, Attitude, Style, Humour", "Kindness, Authority, Speed, Honesty", "Knowledge, Ability, Skills, Habits"], "a": 3, "ex": ["<div class=\"ex-en\">Wrong: not the parts.</div><div class=\"ex-ar\">غلط: مش الأجزاء.</div>", "<div class=\"ex-en\">Wrong: attitude, style and humour are not parts.</div><div class=\"ex-ar\">غلط: دول مش أجزاء الاختصار.</div>", "<div class=\"ex-en\">Wrong: these are not the parts.</div><div class=\"ex-ar\">غلط: دول مش الأجزاء.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>"], "l": "tefl-05"}, {"id": "tefl-m01-test-A:6", "type": "mc4", "q": "<div class=\"q-hard\">The teacher asks 'Who is student A? How much time?' after explaining a role-play. What are these questions called and why are they used?</div><div class=\"q-simple\">What are these questions and why use them?</div><div class=\"q-ar\">المدرّس بيسأل <span class=\"en\">Who is student A? How much time?</span> بعد شرح لعب الأدوار. اسمهم إيه وليه بيتستخدموا؟</div>", "o": ["Icebreaker questions, to relax the class", "Elicitation questions, to test students' vocabulary", "Instruction Check Questions, because nodding students may not really understand", "Peer-feedback questions, to grade classmates"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: they are not icebreakers.</div><div class=\"ex-ar\">غلط: مش كسر جليد.</div>", "<div class=\"ex-en\">Wrong: eliciting pulls out words, ICQs check the task.</div><div class=\"ex-ar\">غلط: الـ <span class=\"en\">elicit</span> بيستخرج كلمات، والـ <span class=\"en\">ICQs</span> بتتأكد من المهمة.</div>", "<div class=\"ex-en\">Right: ICQs check understanding before the task starts.</div><div class=\"ex-ar\">صح: بتتأكد من الفهم قبل بدء المهمة.</div>", "<div class=\"ex-en\">Wrong: they are about instructions, not grading.</div><div class=\"ex-ar\">غلط: عن التعليمات مش تقييم.</div>"], "l": "tefl-07"}]}, {"id": "tefl-m01-test-B", "model": "B", "items": [{"id": "tefl-m01-test-B:1", "type": "mc4", "q": "<div class=\"q-hard\">A learner who forgets a word explains it with other words ('the tool you use to turn small metal things'). Which speaking strategy is this?</div><div class=\"q-simple\">What speaking strategy is this?</div><div class=\"q-ar\">متعلم نسي كلمة وشرحها بكلمات تانية. أي استراتيجية كلام دي؟</div>", "o": ["Inference", "Summarising", "Circumlocution", "Deduction"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: inference is working out meaning from clues.</div><div class=\"ex-ar\">غلط: الاستنتاج هو استخراج المعنى من القرائن.</div>", "<div class=\"ex-en\">Wrong: summarising is a reading strategy.</div><div class=\"ex-ar\">غلط: التلخيص استراتيجية قراءة.</div>", "<div class=\"ex-en\">Right: talking around a word you do not know.</div><div class=\"ex-ar\">صح: بتتكلم حوالين الكلمة.</div>", "<div class=\"ex-en\">Wrong: deduction is used for reading and writing.</div><div class=\"ex-ar\">غلط: الاستدلال للقراءة والكتابة.</div>"], "l": "tefl-04"}, {"id": "tefl-m01-test-B:2", "type": "msel", "q": "<div class=\"q-hard\">Which of the following are among the 19 traits of a competent teacher? Tick all that apply.</div><div class=\"q-simple\">Which are good teacher traits? Tick all that apply.</div><div class=\"q-ar\">أي مما يلي من الصفات الـ 19 للمدرّس الكفء؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["Adjust your own level of English to suit the class", "Give clear, precise instructions", "Reduce teacher talking time and maximise student talking time", "Set low expectations so students feel safe"], "a": [0, 1, 2], "ex": ["<div class=\"ex-en\">Right: there are no prizes for fancy language.</div><div class=\"ex-ar\">صح: مفيش جوايز للغة المعقدة.</div>", "<div class=\"ex-en\">Right: it is trait 8.</div><div class=\"ex-ar\">صح: دي الصفة 8.</div>", "<div class=\"ex-en\">Right: teachers talk far too much.</div><div class=\"ex-ar\">صح: المدرّسين بيتكلموا كتير زيادة.</div>", "<div class=\"ex-en\">Wrong: set high, yet achievable, expectations.</div><div class=\"ex-ar\">غلط: حط توقعات عالية لكن ممكنة.</div>"], "l": "tefl-06"}, {"id": "tefl-m01-test-B:3", "type": "mc3", "q": "<div class=\"q-hard\">Which icebreaker has students find one person for each item on a handout and ask follow-up questions?</div><div class=\"q-simple\">Which icebreaker uses a handout and moving around?</div><div class=\"q-ar\">أي نشاط كسر جليد بيخلي الطلاب يلاقوا شخص لكل بند في ورقة ويسألوا أسئلة متابعة؟</div>", "o": ["Introduce Your Partner", "Teacher Tic Tac Toe", "Find Someone Who"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: pairs interview each other and then present.</div><div class=\"ex-ar\">غلط: أزواج بيعملوا مقابلة ثم يقدموا.</div>", "<div class=\"ex-en\">Wrong: two teams guess questions from a board.</div><div class=\"ex-ar\">غلط: فريقين بيخمنوا أسئلة من لوحة.</div>", "<div class=\"ex-en\">Right: students mingle and ask follow-ups.</div><div class=\"ex-ar\">صح: بيتحركوا ويسألوا أسئلة متابعة.</div>"], "l": "tefl-08"}, {"id": "tefl-m01-test-B:4", "type": "tf", "q": "<div class=\"q-hard\">Constructive feedback must always be positive and never mention problems.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">التغذية الراجعة البنّاءة لازم تكون إيجابية دايمًا ومتذكرش المشاكل.</div>", "o": ["True", "False"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: critical feedback given skilfully can be very useful.</div><div class=\"ex-ar\">غلط: النقد المقدّم بمهارة مفيد جدًا.</div>", "<div class=\"ex-en\">Right: constructive does not mean only positive.</div><div class=\"ex-ar\">صح: البنّاء مش معناه إيجابي بس.</div>"], "l": "tefl-09"}, {"id": "tefl-m01-test-B:5", "type": "mc4", "q": "<div class=\"q-hard\">Which seating layout does the lesson give for opposing-team games?</div><div class=\"q-simple\">Which layout is for team games?</div><div class=\"q-ar\">أي ترتيب جلوس بيذكره الدرس لألعاب الفرق المتنافسة؟</div>", "o": ["Each team in its own corner", "A circle with the teacher inside", "Chairs facing each other in pairs", "A horseshoe"], "a": 0, "ex": ["<div class=\"ex-en\">Right: students get excited about beating the other side.</div><div class=\"ex-ar\">صح: الطلاب بيتحمسوا يغلبوا الفريق التاني.</div>", "<div class=\"ex-en\">Wrong: that is for student-led lessons.</div><div class=\"ex-ar\">غلط: ده للدرس اللي يقوده الطلاب.</div>", "<div class=\"ex-en\">Wrong: that is for A/B role-play.</div><div class=\"ex-ar\">غلط: ده للأدوار <span class=\"en\">A/B</span>.</div>", "<div class=\"ex-en\">Wrong: a horseshoe is for whole-class discussion.</div><div class=\"ex-ar\">غلط: الحدوة للمناقشة الجماعية.</div>"], "l": "tefl-07"}, {"id": "tefl-m01-test-B:6", "type": "mc4", "q": "<div class=\"q-hard\">A Chinese learner says 'lake' when he means 'rake'. What does the lesson say about this?</div><div class=\"q-simple\">Why does a Chinese student say 'lake' for 'rake'?</div><div class=\"q-ar\">متعلم صيني بيقول <span class=\"en\">lake</span> وهو يقصد <span class=\"en\">rake</span>. إيه اللي بيقوله الدرس؟</div>", "o": ["It is caused by the English alphabet", "Chinese learners may confuse l and r", "Spanish speakers always do this", "Chinese has no consonant sounds"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: the issue is sound, not the alphabet.</div><div class=\"ex-ar\">غلط: المشكلة صوتية مش الأبجدية.</div>", "<div class=\"ex-en\">Right: so rake becomes lake and rice becomes lice.</div><div class=\"ex-ar\">صح: فـ <span class=\"en\">rake</span> تبقى <span class=\"en\">lake</span> و<span class=\"en\">rice</span> تبقى <span class=\"en\">lice</span>.</div>", "<div class=\"ex-en\">Wrong: the lesson mentions this for Chinese learners.</div><div class=\"ex-ar\">غلط: الدرس بيذكره للصينيين.</div>", "<div class=\"ex-en\">Wrong: Chinese has consonants.</div><div class=\"ex-ar\">غلط: الصيني فيه حروف ساكنة.</div>"], "l": "tefl-02"}]}, {"id": "tefl-m01-test-C", "model": "C", "items": [{"id": "tefl-m01-test-C:1", "type": "mc4", "q": "<div class=\"q-hard\">Which is one of the seven reasons given for using L1 in class?</div><div class=\"q-simple\">Which is a reason to use L1?</div><div class=\"q-ar\">أي ده من الأسباب السبعة لاستخدام الـ <span class=\"en\">L1</span> في الفصل؟</div>", "o": ["To clarify meaning quickly when an idea is complex", "To replace English whenever students are tired", "To stop students asking questions", "To avoid teaching grammar"], "a": 0, "ex": ["<div class=\"ex-en\">Right: a similar L1 word gets to meaning faster.</div><div class=\"ex-ar\">صح: كلمة مشابهة بالـ <span class=\"en\">L1</span> توصل للمعنى أسرع.</div>", "<div class=\"ex-en\">Wrong: L1 is used judiciously on specific occasions.</div><div class=\"ex-ar\">غلط: الـ <span class=\"en\">L1</span> بيتستخدم في مناسبات محددة.</div>", "<div class=\"ex-en\">Wrong: not a reason.</div><div class=\"ex-ar\">غلط: مش سبب.</div>", "<div class=\"ex-en\">Wrong: not a reason in the lesson.</div><div class=\"ex-ar\">غلط: مش سبب في الدرس.</div>"], "l": "tefl-03"}, {"id": "tefl-m01-test-C:2", "type": "msel", "q": "<div class=\"q-hard\">Which of the following are among the six value groups of the Code of Practice? Tick all that apply.</div><div class=\"q-simple\">Which are value groups? Tick all that apply.</div><div class=\"q-ar\">أي مما يلي من مجموعات القيم الست في ميثاق الممارسة؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["Speed and Efficiency", "Care and Protection", "Honesty and Integrity", "Fairness and Justice"], "a": [1, 2, 3], "ex": ["<div class=\"ex-en\">Wrong: not a value group.</div><div class=\"ex-ar\">غلط: مش مجموعة قيم.</div>", "<div class=\"ex-en\">Right: value group 5.</div><div class=\"ex-ar\">صح: المجموعة 5.</div>", "<div class=\"ex-en\">Right: value group 1.</div><div class=\"ex-ar\">صح: المجموعة 1.</div>", "<div class=\"ex-en\">Right: value group 6.</div><div class=\"ex-ar\">صح: المجموعة 6.</div>"], "l": "tefl-05"}, {"id": "tefl-m01-test-C:3", "type": "mc3", "q": "<div class=\"q-hard\">Indirect communicators convey meaning through hints and stories. What does this usually mean?</div><div class=\"q-simple\">What does an indirect style usually show?</div><div class=\"q-ar\">المتواصل غير المباشر بيوصّل المعنى بالتلميح والحكايات. ده غالبًا معناه إيه؟</div>", "o": ["Anger", "Politeness and respect for the other person", "Weak L2 proficiency"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: not related.</div><div class=\"ex-ar\">غلط: مالوش علاقة.</div>", "<div class=\"ex-en\">Right: do not read it as weak language.</div><div class=\"ex-ar\">صح: متقراهوش كضعف لغة.</div>", "<div class=\"ex-en\">Wrong: it is a communication choice.</div><div class=\"ex-ar\">غلط: ده اختيار تواصل.</div>"], "l": "tefl-04"}, {"id": "tefl-m01-test-C:4", "type": "tf", "q": "<div class=\"q-hard\">English is a tonal language: pitch changes the meaning of words.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">الإنجليزي لغة نغمية: النغمة بتغيّر معنى الكلمات.</div>", "o": ["True", "False"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: in English pitch adds emphasis or emotion only.</div><div class=\"ex-ar\">غلط: في الإنجليزي النغمة بتضيف تأكيد أو عاطفة بس.</div>", "<div class=\"ex-en\">Right: tonal languages are, for example, Chinese and Vietnamese.</div><div class=\"ex-ar\">صح: اللغات النغمية زي الصيني والفيتنامي.</div>"], "l": "tefl-01"}, {"id": "tefl-m01-test-C:5", "type": "mc4", "q": "<div class=\"q-hard\">Why does the lesson say to create a sense of community in the classroom?</div><div class=\"q-simple\">Why create a class community?</div><div class=\"q-ar\">ليه الدرس بيقول اخلق إحساس بالمجتمع في الفصل؟</div>", "o": ["It removes the need for lesson planning", "It stops students speaking English", "The more comfortable students feel, the more they participate, learn and retain", "It lets the teacher talk more"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: planning remains essential.</div><div class=\"ex-ar\">غلط: التخطيط لسه ضروري.</div>", "<div class=\"ex-en\">Wrong: not stated.</div><div class=\"ex-ar\">غلط: مش مذكور.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: you should reduce teacher talk.</div><div class=\"ex-ar\">غلط: لازم تقلل كلام المدرّس.</div>"], "l": "tefl-06"}, {"id": "tefl-m01-test-C:6", "type": "mc4", "q": "<div class=\"q-hard\">Why must a teacher be careful with peer feedback in a class of young learners?</div><div class=\"q-simple\">Why is peer feedback hard for young learners?</div><div class=\"q-ar\">ليه المدرّس لازم يحترس من الـ <span class=\"en\">peer feedback</span> مع الصغار؟</div>", "o": ["They cannot yet think carefully about classmates' work, so detailed feedback is not realistic", "They dislike praise", "Young learners never make mistakes", "Peer feedback is forbidden by the Code"], "a": 0, "ex": ["<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: not stated.</div><div class=\"ex-ar\">غلط: مش مذكور.</div>", "<div class=\"ex-en\">Wrong: not stated.</div><div class=\"ex-ar\">غلط: مش مذكور.</div>", "<div class=\"ex-en\">Wrong: peer feedback is useful for all learners.</div><div class=\"ex-ar\">غلط: مفيد لكل المتعلمين.</div>"], "l": "tefl-09"}]}], "tefl-m2": [{"id": "tefl-m02-test-A", "model": "A", "items": [{"id": "tefl-m02-test-A:1", "type": "mc4", "q": "<div class=\"q-hard\">Which CEFR level is described as 'understands the main points of clear standard input on familiar matters' and 'describes experiences, dreams, hopes and ambitions briefly'?</div><div class=\"q-simple\">Which CEFR level is this?</div><div class=\"q-ar\">أي مستوى <span class=\"en\">CEFR</span> ده اللي بيفهم النقاط الرئيسية للكلام الواضح عن مواضيع مألوفة ويوصف تجارب وأحلام بإيجاز؟</div>", "o": ["A2", "B2", "C1", "B1"], "a": 3, "ex": ["<div class=\"ex-en\">Wrong: A2 handles simple, routine tasks and frequent expressions.</div><div class=\"ex-ar\">غلط: <span class=\"en\">A2</span> للمهام الروتينية والعبارات الشائعة.</div>", "<div class=\"ex-en\">Wrong: B2 understands complex text and explains viewpoints.</div><div class=\"ex-ar\">غلط: <span class=\"en\">B2</span> بيفهم النصوص المعقدة ويشرح وجهات النظر.</div>", "<div class=\"ex-en\">Wrong: C1 follows demanding, longer texts.</div><div class=\"ex-ar\">غلط: <span class=\"en\">C1</span> بيتابع نصوص طويلة صعبة.</div>", "<div class=\"ex-en\">Right: B1 is the Threshold or Intermediate level.</div><div class=\"ex-ar\">صح: <span class=\"en\">B1</span> هو مستوى <span class=\"en\">Threshold</span> أو المتوسط.</div>"], "l": "tefl-10"}, {"id": "tefl-m02-test-A:2", "type": "msel", "q": "<div class=\"q-hard\">Which statements about the CEFR are correct? Tick all that apply.</div><div class=\"q-simple\">Which statements about the CEFR are true? Tick all that apply.</div><div class=\"q-ar\">أي عبارات عن الـ <span class=\"en\">CEFR</span> صح؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["It has six levels, from A1 to C2", "It is only for teaching English", "It is language-neutral, so it works for any language", "It uses can-do statements about what learners can do"], "a": [0, 2, 3], "ex": ["<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: it works for any language.</div><div class=\"ex-ar\">غلط: بيشتغل مع أي لغة.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Right: descriptors focus on ability, not on specific language knowledge.</div><div class=\"ex-ar\">صح: الأوصاف بتركز على القدرة.</div>"], "l": "tefl-10"}, {"id": "tefl-m02-test-A:3", "type": "mc4", "q": "<div class=\"q-hard\">In the lesson, what is 'modelling' when teaching subject pronouns to absolute beginners?</div><div class=\"q-simple\">What is modelling?</div><div class=\"q-ar\">إيه هو الـ <span class=\"en\">modelling</span> في تدريس الضمائر للمبتدئين تمامًا؟</div>", "o": ["Asking students to read silently", "Demonstrating exactly what you mean by pointing and using visuals", "Writing the whole list on the board for students to copy", "Using a model student as an example"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: not modelling.</div><div class=\"ex-ar\">غلط: مش <span class=\"en\">modelling</span>.</div>", "<div class=\"ex-en\">Right: for example pointing to yourself and saying 'I am a teacher'.</div><div class=\"ex-ar\">صح: زي ما تشاور على نفسك وتقول <span class=\"en\">I am a teacher</span>.</div>", "<div class=\"ex-en\">Wrong: the lesson says do not just write the list and ask students to copy.</div><div class=\"ex-ar\">غلط: الدرس بيقول متكتبش القايمة بس.</div>", "<div class=\"ex-en\">Wrong: not what the term means.</div><div class=\"ex-ar\">غلط: مش معنى المصطلح.</div>"], "l": "tefl-11"}, {"id": "tefl-m02-test-A:4", "type": "tf", "q": "<div class=\"q-hard\">Absolute beginners know nothing of English, while false beginners have picked up some English informally and may have bad habits.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">المبتدئ المطلق معندوش أي معرفة بالإنجليزي، أما الـ <span class=\"en\">false beginner</span> اتعلم شوية بشكل غير رسمي وممكن يكون عنده عادات سيئة.</div>", "o": ["True", "False"], "a": 0, "ex": ["<div class=\"ex-en\">Absolute beginners often catch up quickly, because their intrinsic motivation is high.</div><div class=\"ex-ar\">المبتدئين المطلقين غالبًا بيلحقوا بسرعة لأن دافعيتهم الداخلية عالية.</div>", "<div class=\"ex-en\">Wrong: the statement is true.</div><div class=\"ex-ar\">غلط: العبارة صح.</div>"], "l": "tefl-11"}, {"id": "tefl-m02-test-A:5", "type": "mc4", "q": "<div class=\"q-hard\">Which pair is correct about 'have to' and 'don't have to'?</div><div class=\"q-simple\">What do 'have to' and 'don't have to' mean?</div><div class=\"q-ar\">أي زوج صح عن <span class=\"en\">have to</span> و<span class=\"en\">don't have to</span>؟</div>", "o": ["Both mean it is advisable", "'Have to' is obligatory; 'don't have to' is possible but not necessary, not forbidden", "They are exact opposites, and 'don't have to' means forbidden", "Both mean it is forbidden"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: advisable is 'should'.</div><div class=\"ex-ar\">غلط: المستحب هو <span class=\"en\">should</span>.</div>", "<div class=\"ex-en\">Right: they are not exact opposites in the way you might expect.</div><div class=\"ex-ar\">صح: مش عكس تمامًا زي ما بنتوقع.</div>", "<div class=\"ex-en\">Wrong: forbidden is 'must not' or 'cannot'.</div><div class=\"ex-ar\">غلط: الممنوع هو <span class=\"en\">must not</span> أو <span class=\"en\">cannot</span>.</div>", "<div class=\"ex-en\">Wrong: neither means forbidden.</div><div class=\"ex-ar\">غلط: ولا واحد معناه ممنوع.</div>"], "l": "tefl-12"}, {"id": "tefl-m02-test-A:6", "type": "mc4", "q": "<div class=\"q-hard\">Which of the following is correct English but not a complete sentence?</div><div class=\"q-simple\">Which is not a full sentence?</div><div class=\"q-ar\">أي مما يلي إنجليزي صحيح لكنه مش جملة كاملة؟</div>", "o": ["He phoned.", "Will you help me?", "Made in France", "Carlos smiled."], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: it has a subject and a verb.</div><div class=\"ex-ar\">غلط: فيها فاعل وفعل.</div>", "<div class=\"ex-en\">Wrong: it has the subject 'you' and the verb 'will help'.</div><div class=\"ex-ar\">غلط: فيها الفاعل <span class=\"en\">you</span> والفعل <span class=\"en\">will help</span>.</div>", "<div class=\"ex-en\">Right: it has no subject.</div><div class=\"ex-ar\">صح: مفيهاش فاعل.</div>", "<div class=\"ex-en\">Wrong: a complete simple sentence.</div><div class=\"ex-ar\">غلط: جملة بسيطة كاملة.</div>"], "l": "tefl-15"}]}, {"id": "tefl-m02-test-B", "model": "B", "items": [{"id": "tefl-m02-test-B:1", "type": "mc4", "q": "<div class=\"q-hard\">At which level does the lesson's grammar map place relative clauses and the passive?</div><div class=\"q-simple\">At which level are relative clauses taught?</div><div class=\"q-ar\">في أي مستوى بتتدرّس الجمل الموصولة والمبني للمجهول حسب خريطة القواعد؟</div>", "o": ["Beginner", "Intermediate", "Advanced", "Elementary"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: beginner covers pronouns, verb be and articles.</div><div class=\"ex-ar\">غلط: المبتدئ بيغطي الضمائر وفعل <span class=\"en\">be</span> والأدوات.</div>", "<div class=\"ex-en\">Right: intermediate includes passives, relative clauses and reported speech.</div><div class=\"ex-ar\">صح: المتوسط فيه المبني للمجهول والجمل الموصولة والكلام المنقول.</div>", "<div class=\"ex-en\">Wrong: advanced covers inversion, cleft sentences and mixed conditionals.</div><div class=\"ex-ar\">غلط: المتقدم بيغطي القلب والجمل المشقوقة والشرط المختلط.</div>", "<div class=\"ex-en\">Wrong: elementary covers present simple, past simple and so on.</div><div class=\"ex-ar\">غلط: الأساسي بيغطي المضارع البسيط والماضي البسيط.</div>"], "l": "tefl-10"}, {"id": "tefl-m02-test-B:2", "type": "msel", "q": "<div class=\"q-hard\">Which of these are among the nine tips for teaching absolute beginners? Tick all that apply.</div><div class=\"q-simple\">Which are tips for absolute beginners? Tick all that apply.</div><div class=\"q-ar\">أي من دي من النصائح التسع لتدريس المبتدئين المطلقين؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["Write a lot on the board while you keep explaining", "Be animated, with mime and sound effects", "Learn a bit of their L1", "Review constantly, starting every class with a review"], "a": [1, 2, 3], "ex": ["<div class=\"ex-en\">Wrong: beginners cannot multi-task. Do one thing at a time.</div><div class=\"ex-ar\">غلط: المبتدئين مبيعرفوش يعملوا حاجتين. حاجة واحدة في كل مرة.</div>", "<div class=\"ex-en\">Right: not all learning has to be serious.</div><div class=\"ex-ar\">صح: مش كل التعلم لازم يبقى جاد.</div>", "<div class=\"ex-en\">Right: they see you as a partner in learning.</div><div class=\"ex-ar\">صح: بيشوفوك شريك في التعلم.</div>", "<div class=\"ex-en\">Right: you are their textbook and study guide.</div><div class=\"ex-ar\">صح: إنت كتابهم ودليل مذاكرتهم.</div>"], "l": "tefl-11"}, {"id": "tefl-m02-test-B:3", "type": "mc4", "q": "<div class=\"q-hard\">In 'The boy, who we met yesterday, is very nice', why can 'that' not replace 'who'?</div><div class=\"q-simple\">Why can't we use 'that' here?</div><div class=\"q-ar\">ليه مينفعش نستخدم <span class=\"en\">that</span> بدل <span class=\"en\">who</span> في <span class=\"en\">The boy, who we met yesterday, is very nice</span>؟</div>", "o": ["'That' always needs a comma", "'That' is only for objects", "'Who' is always required after a comma-free noun", "The commas make it a non-defining clause that only adds extra information"], "a": 3, "ex": ["<div class=\"ex-en\">Wrong: not true.</div><div class=\"ex-ar\">غلط: مش صح.</div>", "<div class=\"ex-en\">Wrong: 'that' can be used for people in defining clauses.</div><div class=\"ex-ar\">غلط: <span class=\"en\">that</span> ممكن للأشخاص في الجمل المحدِّدة.</div>", "<div class=\"ex-en\">Wrong: not true.</div><div class=\"ex-ar\">غلط: مش صح.</div>", "<div class=\"ex-en\">Right: we already know which boy.</div><div class=\"ex-ar\">صح: إحنا عارفين أنهي ولد.</div>"], "l": "tefl-12"}, {"id": "tefl-m02-test-B:4", "type": "tf", "q": "<div class=\"q-hard\">The first verb in a sentence can decide the form of the second verb, for example 'enjoy' + gerund and 'decide' + to-infinitive.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">الفعل الأول في الجملة ممكن يحدد شكل الفعل التاني، زي <span class=\"en\">enjoy</span> + <span class=\"en\">gerund</span> و<span class=\"en\">decide</span> + <span class=\"en\">to-infinitive</span>.</div>", "o": ["True", "False"], "a": 0, "ex": ["<div class=\"ex-en\">Modal verbs are always followed by the infinitive without 'to'.</div><div class=\"ex-ar\">الأفعال الناقصة دايمًا بعدها المصدر من غير <span class=\"en\">to</span>.</div>", "<div class=\"ex-en\">Wrong: the statement is true.</div><div class=\"ex-ar\">غلط: العبارة صح.</div>"], "l": "tefl-12"}, {"id": "tefl-m02-test-B:5", "type": "mc4", "q": "<div class=\"q-hard\">In 'She sings rock and roll tunes', is 'sings' transitive or intransitive?</div><div class=\"q-simple\">Is 'sings' transitive here?</div><div class=\"q-ar\">في <span class=\"en\">She sings rock and roll tunes</span>، هل <span class=\"en\">sings</span> متعدٍّ أم لازم؟</div>", "o": ["It is an adverb", "Intransitive, because 'sings' never takes an object", "Transitive, because the tunes receive the action", "Transitive, because it has an indirect object"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: it is a verb.</div><div class=\"ex-ar\">غلط: فعل.</div>", "<div class=\"ex-en\">Wrong: many verbs can be both.</div><div class=\"ex-ar\">غلط: أفعال كتير ممكن تكون الاتنين.</div>", "<div class=\"ex-en\">Right: the same verb can be intransitive in 'She sings every day'.</div><div class=\"ex-ar\">صح: نفس الفعل ممكن يبقى لازم في <span class=\"en\">She sings every day</span>.</div>", "<div class=\"ex-en\">Wrong: there is no indirect object.</div><div class=\"ex-ar\">غلط: مفيش مفعول غير مباشر.</div>"], "l": "tefl-13"}, {"id": "tefl-m02-test-B:6", "type": "tf", "q": "<div class=\"q-hard\">A subordinate clause is also called an independent clause.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">الجملة الفرعية اسمها كمان جملة مستقلة.</div>", "o": ["True", "False"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: the statement is false. The subordinate clause is the dependent clause. The main clause is the independent one.</div><div class=\"ex-ar\">غلط: العبارة غلط. الفرعية هي التابعة، والرئيسية هي المستقلة.</div>", "<div class=\"ex-en\">The subordinate clause is the dependent clause. The main clause is the independent one.</div><div class=\"ex-ar\">الفرعية هي التابعة، والرئيسية هي المستقلة.</div>"], "l": "tefl-14"}]}]};window.MODPRACT={"tefl-m1": [{"id": "tefl-m01-practice-A", "model": "A", "items": [{"id": "tefl-m01-practice-A:1", "type": "mc4", "q": "<div class=\"q-hard\">Why do English articles cause huge difficulty for some students?</div><div class=\"q-simple\">Why are articles hard?</div><div class=\"q-ar\">ليه أدوات التعريف في الإنجليزي بتسبب صعوبة كبيرة لبعض الطلاب؟</div>", "o": ["Articles are only used in writing", "Their first language has no articles at all", "Articles change with the person", "English has more than 26 letters"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: not stated.</div><div class=\"ex-ar\">غلط: مش مذكور.</div>", "<div class=\"ex-en\">Right: the concept is new to them.</div><div class=\"ex-ar\">صح: الفكرة جديدة عليهم.</div>", "<div class=\"ex-en\">Wrong: articles do not change with the person.</div><div class=\"ex-ar\">غلط: الأدوات مبتتغيرش مع الشخص.</div>", "<div class=\"ex-en\">Wrong: English has 26 basic letters.</div><div class=\"ex-ar\">غلط: الإنجليزي 26 حرف أساسي.</div>"], "l": "tefl-01"}, {"id": "tefl-m01-practice-A:2", "type": "msel", "q": "<div class=\"q-hard\">Which of the following are examples of English words borrowed from other languages in the lesson? Tick all that apply.</div><div class=\"q-simple\">Which words came from other languages? Tick all that apply.</div><div class=\"q-ar\">أي من الكلمات دي اتاخدت من لغات تانية حسب الدرس؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["cargo (from Spanish)", "clothes (from Latin)", "barbecue (from Spanish)", "alligator (from Spanish)"], "a": [0, 2, 3], "ex": ["<div class=\"ex-en\">Right: from cargar, to load.</div><div class=\"ex-ar\">صح: من <span class=\"en\">cargar</span>.</div>", "<div class=\"ex-en\">Wrong: 'clothes' is given as a hard sound, not a borrowed word.</div><div class=\"ex-ar\">غلط: <span class=\"en\">clothes</span> مذكورة كصوت صعب مش كلمة مستعارة.</div>", "<div class=\"ex-en\">Right: from barbacoa.</div><div class=\"ex-ar\">صح: من <span class=\"en\">barbacoa</span>.</div>", "<div class=\"ex-en\">Right: from el lagarto.</div><div class=\"ex-ar\">صح: من <span class=\"en\">el lagarto</span>.</div>"], "l": "tefl-01"}, {"id": "tefl-m01-practice-A:3", "type": "mc4", "q": "<div class=\"q-hard\">Why do Spanish learners often say 'Espain'?</div><div class=\"q-simple\">Why 'Espain'?</div><div class=\"q-ar\">ليه المتعلمين الإسبان بيقولوا <span class=\"en\">Espain</span>؟</div>", "o": ["They confuse v and b", "They use a tone", "They drop the final consonant", "Spanish words do not start with s before another consonant, so they add an e"], "a": 3, "ex": ["<div class=\"ex-en\">Wrong: a different problem.</div><div class=\"ex-ar\">غلط: مشكلة تانية.</div>", "<div class=\"ex-en\">Wrong: Spanish is not tonal.</div><div class=\"ex-ar\">غلط: الإسباني مش نغمي.</div>", "<div class=\"ex-en\">Wrong: this is typical of Chinese learners.</div><div class=\"ex-ar\">غلط: ده أقرب للصينيين.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>"], "l": "tefl-02"}, {"id": "tefl-m01-practice-A:4", "type": "tf", "q": "<div class=\"q-hard\">Spanish has many cognates with English, which is an advantage that Chinese learners do not have.</div><div class=\"q-simple\">True or false: Spanish learners have many cognates.</div><div class=\"q-ar\">الإسباني فيه كلمات كتير مشتركة مع الإنجليزي وده ميزة الصينيين مش عندهم.</div>", "o": ["True", "False"], "a": 0, "ex": ["<div class=\"ex-en\">Cognates share a history and look and mean alike. Chinese has very few.</div><div class=\"ex-ar\">الكلمات المشتركة ليها تاريخ مشترك وشكل ومعنى متقاربين. الصيني فيه قليل.</div>", "<div class=\"ex-en\">Wrong: the statement is true.</div><div class=\"ex-ar\">غلط: العبارة صح.</div>"], "l": "tefl-02"}, {"id": "tefl-m01-practice-A:5", "type": "mc4", "q": "<div class=\"q-hard\">What is an L2?</div><div class=\"q-simple\">What is L2?</div><div class=\"q-ar\">إيه هي الـ <span class=\"en\">L2</span>؟</div>", "o": ["A teaching method", "A school level", "The second or foreign language a person is learning", "A person's first language"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: not a method.</div><div class=\"ex-ar\">غلط: مش طريقة تدريس.</div>", "<div class=\"ex-en\">Wrong: not a level.</div><div class=\"ex-ar\">غلط: مش مستوى.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: that is L1.</div><div class=\"ex-ar\">غلط: دي الـ <span class=\"en\">L1</span>.</div>"], "l": "tefl-03"}, {"id": "tefl-m01-practice-A:6", "type": "msel", "q": "<div class=\"q-hard\">Which of these describe a child learning her L1? Tick all that apply.</div><div class=\"q-simple\">How do children learn L1? Tick all that apply.</div><div class=\"q-ar\">أي من دي بيوصف طفل بيتعلم لغته الأولى؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["Immersed in the language from birth", "Not often corrected", "Motivated to communicate her needs", "Receives little attention"], "a": [0, 1, 2], "ex": ["<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Right: she learns by playing and experimenting.</div><div class=\"ex-ar\">صح: بتتعلم باللعب والتجريب.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: she gets a lot of attention and praise.</div><div class=\"ex-ar\">غلط: بتاخد اهتمام ومديح كتير.</div>"], "l": "tefl-03"}, {"id": "tefl-m01-practice-A:7", "type": "mc4", "q": "<div class=\"q-hard\">Which influence on L2 learning is shown when a learner expects a formal, strict teacher?</div><div class=\"q-simple\">Which influence is this?</div><div class=\"q-ar\">أي عامل مؤثر على تعلم الـ <span class=\"en\">L2</span> بيظهر لما المتعلم يتوقع مدرّس رسمي وصارم؟</div>", "o": ["Gender", "Appropriate topics", "Prior learning", "Intellect"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: gender is a separate influence.</div><div class=\"ex-ar\">غلط: الجنس عامل منفصل.</div>", "<div class=\"ex-en\">Wrong: this is about what topics are acceptable.</div><div class=\"ex-ar\">غلط: ده عن المواضيع المقبولة.</div>", "<div class=\"ex-en\">Right: learners bring expectations from their home school system.</div><div class=\"ex-ar\">صح: المتعلمين بيجيبوا توقعات من نظامهم المدرسي.</div>", "<div class=\"ex-en\">Wrong: this is about expectation.</div><div class=\"ex-ar\">غلط: ده عن التوقع.</div>"], "l": "tefl-04"}, {"id": "tefl-m01-practice-A:8", "type": "tf", "q": "<div class=\"q-hard\">In an idea-focused style, disagreeing with someone's idea is seen as a personal attack.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">في الأسلوب المركّز على الفكرة، الخلاف مع فكرة حد بيتشاف كهجوم شخصي.</div>", "o": ["True", "False"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: the statement is true: The idea and the person are separate. It is the person-focused style where disagreement feels like an attack.</div><div class=\"ex-ar\">غلط: العبارة صح: الفكرة والشخص منفصلين. الأسلوب المركّز على الشخص هو اللي الخلاف فيه بيتحس كهجوم.</div>", "<div class=\"ex-en\">The idea and the person are separate. It is the person-focused style where disagreement feels like an attack.</div><div class=\"ex-ar\">الفكرة والشخص منفصلين. الأسلوب المركّز على الشخص هو اللي الخلاف فيه بيتحس كهجوم.</div>"], "l": "tefl-04"}, {"id": "tefl-m01-practice-A:9", "type": "mc4", "q": "<div class=\"q-hard\">In the lesson, what does the Code of Practice say about a teacher using her authority?</div><div class=\"q-simple\">What does the Code say about authority?</div><div class=\"q-ar\">إيه اللي بيقوله الميثاق عن استخدام المدرّس لسلطته؟</div>", "o": ["Authority is only for the head teacher", "Never abuse a position of authority for financial, political or personal gain", "Authority should be hidden from students", "Use authority to collect private lessons"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: not stated.</div><div class=\"ex-ar\">غلط: مش مذكور.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: not stated.</div><div class=\"ex-ar\">غلط: مش مذكور.</div>", "<div class=\"ex-en\">Wrong: this breaks the Code.</div><div class=\"ex-ar\">غلط: ده بيخالف الميثاق.</div>"], "l": "tefl-05"}, {"id": "tefl-m01-practice-A:10", "type": "msel", "q": "<div class=\"q-hard\">Which actions fit 'Care and Protection'? Tick all that apply.</div><div class=\"q-simple\">Which actions protect students? Tick all that apply.</div><div class=\"q-ar\">أي تصرفات بتناسب «الرعاية والحماية»؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["Making reasonable efforts to protect students from harm", "Being generous with praise", "Following the school's student protection policies", "Embarrassing students who give wrong answers"], "a": [0, 1, 2], "ex": ["<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: the Code forbids embarrassment and harassment.</div><div class=\"ex-ar\">غلط: الميثاق بيمنع الإحراج والتحرش.</div>"], "l": "tefl-05"}, {"id": "tefl-m01-practice-A:11", "type": "mc4", "q": "<div class=\"q-hard\">Which trait is shown when a teacher lets a fluent speaking task continue and corrects mistakes afterwards?</div><div class=\"q-simple\">Which trait is this?</div><div class=\"q-ar\">أي صفة بتظهر لما المدرّس يسيب مهمة كلام سلسة تكمل ويصحح الأخطاء بعدين؟</div>", "o": ["Setting low expectations", "Choosing appropriate moments for correcting learners' language", "Ignoring assessment", "Increasing teacher talking time"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: not related.</div><div class=\"ex-ar\">غلط: مالهاش علاقة.</div>", "<div class=\"ex-en\">Right: it is trait 9.</div><div class=\"ex-ar\">صح: دي الصفة 9.</div>", "<div class=\"ex-en\">Wrong: fair assessment is trait 13.</div><div class=\"ex-ar\">غلط: التقييم العادل الصفة 13.</div>", "<div class=\"ex-en\">Wrong: the lesson says to reduce it.</div><div class=\"ex-ar\">غلط: الدرس بيقول قلله.</div>"], "l": "tefl-06"}, {"id": "tefl-m01-practice-A:12", "type": "tf", "q": "<div class=\"q-hard\">Setting high but achievable expectations can raise students' achievement.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">وضع توقعات عالية لكن ممكنة ممكن يرفع تحصيل الطلاب.</div>", "o": ["True", "False"], "a": 0, "ex": ["<div class=\"ex-en\">Students generally give as much as the teacher expects.</div><div class=\"ex-ar\">الطلاب غالبًا بيدّوا بقدر ما المدرّس بيتوقع.</div>", "<div class=\"ex-en\">Wrong: the statement is true.</div><div class=\"ex-ar\">غلط: العبارة صح.</div>"], "l": "tefl-06"}, {"id": "tefl-m01-practice-A:13", "type": "mc4", "q": "<div class=\"q-hard\">You want students to lead the lesson themselves. Which layout fits?</div><div class=\"q-simple\">Which layout is for student-led lessons?</div><div class=\"q-ar\">عايز الطلاب يقودوا الحصة بنفسهم. أي ترتيب مناسب؟</div>", "o": ["A circle, with the teacher inside", "Islands", "Straight rows", "Corners"], "a": 0, "ex": ["<div class=\"ex-en\">Right: everyone is on an equal level.</div><div class=\"ex-ar\">صح: الكل في مستوى متساوي.</div>", "<div class=\"ex-en\">Wrong: islands suit group work.</div><div class=\"ex-ar\">غلط: الجزر للشغل الجماعي.</div>", "<div class=\"ex-en\">Wrong: rows do not support student leading.</div><div class=\"ex-ar\">غلط: الصفوف مبتدعمش قيادة الطلاب.</div>", "<div class=\"ex-en\">Wrong: corners suit opposing teams.</div><div class=\"ex-ar\">غلط: الأركان للفرق المتنافسة.</div>"], "l": "tefl-07"}, {"id": "tefl-m01-practice-A:14", "type": "mc4", "q": "<div class=\"q-hard\">Which rule is an INEFFECTIVE classroom rule, according to the lesson?</div><div class=\"q-simple\">Which rule does not work well?</div><div class=\"q-ar\">أي قاعدة غير فعّالة في الفصل حسب الدرس؟</div>", "o": ["Only speak English in the classroom", "Be on time for class", "Switch off your mobile phone", "Silence in the classroom"], "a": 3, "ex": ["<div class=\"ex-en\">Wrong: this is effective.</div><div class=\"ex-ar\">غلط: دي فعّالة.</div>", "<div class=\"ex-en\">Wrong: this is effective.</div><div class=\"ex-ar\">غلط: دي فعّالة.</div>", "<div class=\"ex-en\">Wrong: this is effective.</div><div class=\"ex-ar\">غلط: دي فعّالة.</div>", "<div class=\"ex-en\">Right: it blocks communication practice.</div><div class=\"ex-ar\">صح: بتمنع ممارسة التواصل.</div>"], "l": "tefl-07"}, {"id": "tefl-m01-practice-A:15", "type": "mc4", "q": "<div class=\"q-hard\">Why are icebreakers also useful as warmers?</div><div class=\"q-simple\">Why use icebreakers as warmers?</div><div class=\"q-ar\">ليه أنشطة كسر الجليد مفيدة كمان كـ <span class=\"en\">warmers</span>؟</div>", "o": ["They are only for substitutes", "They replace the lesson", "They wake the class up and introduce the topic of the lesson", "They test last week's grammar"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: they are also for new courses and normal lessons.</div><div class=\"ex-ar\">غلط: كمان للكورسات الجديدة والحصص العادية.</div>", "<div class=\"ex-en\">Wrong: they support it.</div><div class=\"ex-ar\">غلط: بتدعمه.</div>", "<div class=\"ex-en\">Right: use a variety to match the task.</div><div class=\"ex-ar\">صح: استخدم تنوع يناسب المهمة.</div>", "<div class=\"ex-en\">Wrong: not their purpose.</div><div class=\"ex-ar\">غلط: مش غرضها.</div>"], "l": "tefl-08"}, {"id": "tefl-m01-practice-A:16", "type": "tf", "q": "<div class=\"q-hard\">In Introduce Your Partner, students practise third person verb forms such as 'he lives'.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">في <span class=\"en\">Introduce Your Partner</span>، الطلاب بيتدربوا على الأفعال مع الغائب زي <span class=\"en\">he lives</span>.</div>", "o": ["True", "False"], "a": 0, "ex": ["<div class=\"ex-en\">Introducing a partner instead of yourself practises the 's' form.</div><div class=\"ex-ar\">تقديم الزميل بدل النفس بيدرّب على صيغة <span class=\"en\">s</span>.</div>", "<div class=\"ex-en\">Wrong: the statement is true.</div><div class=\"ex-ar\">غلط: العبارة صح.</div>"], "l": "tefl-08"}, {"id": "tefl-m01-practice-A:17", "type": "mc4", "q": "<div class=\"q-hard\">Which of the following is a good example of descriptive, not evaluative, feedback?</div><div class=\"q-simple\">Which comment is descriptive?</div><div class=\"q-ar\">أي تعليق ده مثال كويس لتغذية راجعة وصفية مش تقييمية؟</div>", "o": ["That was poor.", "The way you stayed calm and focused helped everyone cope.", "You handled that well.", "You were brilliant."], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: evaluative and not specific.</div><div class=\"ex-ar\">غلط: تقييمي وغير محدد.</div>", "<div class=\"ex-en\">Right: it says what you saw and its effect.</div><div class=\"ex-ar\">صح: بيقول اللي اتشاف وتأثيره.</div>", "<div class=\"ex-en\">Wrong: this is evaluative.</div><div class=\"ex-ar\">غلط: ده تقييمي.</div>", "<div class=\"ex-en\">Wrong: too general and evaluative.</div><div class=\"ex-ar\">غلط: عام وتقييمي.</div>"], "l": "tefl-09"}, {"id": "tefl-m01-practice-A:18", "type": "msel", "q": "<div class=\"q-hard\">Which of the following are among the seven rules of constructive feedback? Tick all that apply.</div><div class=\"q-simple\">Which are rules of feedback? Tick all that apply.</div><div class=\"q-ar\">أي من دي من القواعد السبع للتغذية الراجعة البنّاءة؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["Demand an immediate change", "Be specific", "Own the feedback with 'I think' or 'I feel'", "Start with the positive"], "a": [1, 2, 3], "ex": ["<div class=\"ex-en\">Wrong: rule 7 says to leave the recipient with a choice.</div><div class=\"ex-ar\">غلط: القاعدة 7 بتقول سيب للمتلقي اختيار.</div>", "<div class=\"ex-en\">Right: rule 2.</div><div class=\"ex-ar\">صح: القاعدة 2.</div>", "<div class=\"ex-en\">Right: rule 6.</div><div class=\"ex-ar\">صح: القاعدة 6.</div>", "<div class=\"ex-en\">Right: rule 1.</div><div class=\"ex-ar\">صح: القاعدة 1.</div>"], "l": "tefl-09"}, {"id": "tefl-m01-practice-A:19", "type": "mc4", "q": "<div class=\"q-hard\">A learner is shy about criticising classmates in peer feedback. What does the lesson suggest?</div><div class=\"q-simple\">How can a shy learner give peer feedback?</div><div class=\"q-ar\">متعلم خجول من انتقاد زملائه في الـ <span class=\"en\">peer feedback</span>. إيه اللي بيقترحه الدرس؟</div>", "o": ["Let the strongest student criticise everyone", "Give a handout that asks for notes on certain areas, like structure or fluency", "Ask for only general comments", "Skip peer feedback for the whole course"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: not suggested.</div><div class=\"ex-ar\">غلط: مش مقترح.</div>", "<div class=\"ex-en\">Right: specific areas are easier than general comments.</div><div class=\"ex-ar\">صح: المجالات المحددة أسهل من التعليقات العامة.</div>", "<div class=\"ex-en\">Wrong: general comments are harder for shy students.</div><div class=\"ex-ar\">غلط: التعليقات العامة أصعب للخجولين.</div>", "<div class=\"ex-en\">Wrong: it is useful for all learners.</div><div class=\"ex-ar\">غلط: مفيد لكل المتعلمين.</div>"], "l": "tefl-09"}]}], "tefl-m2": [{"id": "tefl-m02-practice-A", "model": "A", "items": [{"id": "tefl-m02-practice-A:1", "type": "mc4", "q": "<div class=\"q-hard\">What does the CEFR stand for?</div><div class=\"q-simple\">What does CEFR mean?</div><div class=\"q-ar\">إيه معنى <span class=\"en\">CEFR</span>؟</div>", "o": ["Central English Foundation Research", "Cambridge English First Revision", "Common English Fluency Rating", "Common European Framework of Reference"], "a": 3, "ex": ["<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Wrong: Cambridge exams are a different system.</div><div class=\"ex-ar\">غلط: امتحانات كامبريدج نظام تاني.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>"], "l": "tefl-10"}, {"id": "tefl-m02-practice-A:2", "type": "mc4", "q": "<div class=\"q-hard\">Which CEFR band includes B1 and B2?</div><div class=\"q-simple\">Which band has B1 and B2?</div><div class=\"q-ar\">أي مستوى عام في <span class=\"en\">CEFR</span> فيه <span class=\"en\">B1</span> و<span class=\"en\">B2</span>؟</div>", "o": ["Proficient User", "Independent User", "Beginner User", "Basic User"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: C1 and C2.</div><div class=\"ex-ar\">غلط: <span class=\"en\">C1</span> و<span class=\"en\">C2</span>.</div>", "<div class=\"ex-en\">Right: A is Basic, B is Independent, C is Proficient.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: not a CEFR band.</div><div class=\"ex-ar\">غلط: مش مستوى <span class=\"en\">CEFR</span>.</div>", "<div class=\"ex-en\">Wrong: A1 and A2.</div><div class=\"ex-ar\">غلط: <span class=\"en\">A1</span> و<span class=\"en\">A2</span>.</div>"], "l": "tefl-10"}, {"id": "tefl-m02-practice-A:3", "type": "msel", "q": "<div class=\"q-hard\">Which belong to linguistic competence in the CEFR? Tick all that apply.</div><div class=\"q-simple\">What is linguistic competence? Tick all that apply.</div><div class=\"q-ar\">أي من دي ضمن الكفاءة اللغوية في <span class=\"en\">CEFR</span>؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["Syntax", "Phonology", "Lexis", "Rules of address and politeness"], "a": [0, 1, 2], "ex": ["<div class=\"ex-en\">Right: how words form sentences.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Right: relations among speech sounds.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Right: words and phrases.</div><div class=\"ex-ar\">صح: كلمات وعبارات.</div>", "<div class=\"ex-en\">Wrong: that is socio-linguistic competence.</div><div class=\"ex-ar\">غلط: دي الكفاءة الاجتماعية اللغوية.</div>"], "l": "tefl-10"}, {"id": "tefl-m02-practice-A:4", "type": "mc4", "q": "<div class=\"q-hard\">Why can false beginners be hard to teach?</div><div class=\"q-simple\">Why are false beginners tricky?</div><div class=\"q-ar\">ليه الـ <span class=\"en\">false beginners</span> ممكن يبقوا صعبين في التدريس؟</div>", "o": ["Surface knowledge can hide bad habits, and they may think they already know the material", "They have too much motivation", "They know no English", "They refuse all pair work"], "a": 0, "ex": ["<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: their motivation can suffer.</div><div class=\"ex-ar\">غلط: دافعيتهم ممكن تقل.</div>", "<div class=\"ex-en\">Wrong: that is an absolute beginner.</div><div class=\"ex-ar\">غلط: ده المبتدئ المطلق.</div>", "<div class=\"ex-en\">Wrong: not stated.</div><div class=\"ex-ar\">غلط: مش مذكور.</div>"], "l": "tefl-11"}, {"id": "tefl-m02-practice-A:5", "type": "mc4", "q": "<div class=\"q-hard\">Which of the following is a trick the lesson gives for learning a student's name when you forget it?</div><div class=\"q-simple\">How can you learn a forgotten name?</div><div class=\"q-ar\">أي مما يلي حيلة بيذكرها الدرس لتعلم اسم طالب نسيته؟</div>", "o": ["Describe the student ('a boy with a red shirt near the window') and let the class say the name", "Call him 'student' all term", "Ask him to write his name 10 times", "Skip all questions to him"], "a": 0, "ex": ["<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: personal connection matters.</div><div class=\"ex-ar\">غلط: العلاقة الشخصية مهمة.</div>", "<div class=\"ex-en\">Wrong: not suggested.</div><div class=\"ex-ar\">غلط: مش مقترح.</div>", "<div class=\"ex-en\">Wrong: not a solution.</div><div class=\"ex-ar\">غلط: مش حل.</div>"], "l": "tefl-11"}, {"id": "tefl-m02-practice-A:6", "type": "tf", "q": "<div class=\"q-hard\">At elementary level, every pronoun except I has two negative contractions with 'be': for example 'you're not' and 'you aren't'.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">في المستوى الأساسي، كل ضمير ماعدا <span class=\"en\">I</span> ليه صيغتين للنفي مع <span class=\"en\">be</span>: زي <span class=\"en\">you're not</span> و<span class=\"en\">you aren't</span>.</div>", "o": ["True", "False"], "a": 0, "ex": ["<div class=\"ex-en\">'I am not' has only 'I'm not'.</div><div class=\"ex-ar\"><span class=\"en\">I am not</span> ليها <span class=\"en\">I'm not</span> بس.</div>", "<div class=\"ex-en\">Wrong: the statement is true.</div><div class=\"ex-ar\">غلط: العبارة صح.</div>"], "l": "tefl-11"}, {"id": "tefl-m02-practice-A:7", "type": "mc4", "q": "<div class=\"q-hard\">Which modal expresses that something is 'forbidden'?</div><div class=\"q-simple\">Which modal means forbidden?</div><div class=\"q-ar\">أي فعل ناقص بيعبّر عن إن حاجة ممنوعة؟</div>", "o": ["Don't have to", "Must not", "Should", "May"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: not necessary, not forbidden.</div><div class=\"ex-ar\">غلط: مش ضروري مش ممنوع.</div>", "<div class=\"ex-en\">Right: must not and cannot mean forbidden.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: advisable.</div><div class=\"ex-ar\">غلط: مستحب.</div>", "<div class=\"ex-en\">Wrong: it is possible.</div><div class=\"ex-ar\">غلط: ممكن.</div>"], "l": "tefl-12"}, {"id": "tefl-m02-practice-A:8", "type": "mc4", "q": "<div class=\"q-hard\">How many relative pronouns are listed, and which relative adverbs?</div><div class=\"q-simple\">What are the relative pronouns and adverbs?</div><div class=\"q-ar\">كام ضمير وصل مذكور، وإيه ظروف الوصل؟</div>", "o": ["Five pronouns and no adverbs", "Five pronouns (who, which, whom, that, whose) and three adverbs (where, when, why)", "Three pronouns and five adverbs", "Seven pronouns and two adverbs"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: there are three adverbs.</div><div class=\"ex-ar\">غلط: فيه ثلاث ظروف.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: reversed.</div><div class=\"ex-ar\">غلط: معكوس.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>"], "l": "tefl-12"}, {"id": "tefl-m02-practice-A:9", "type": "mc4", "q": "<div class=\"q-hard\">Which sentence is a correct passive of 'Somebody has stolen my wallet'?</div><div class=\"q-simple\">What is the passive of this sentence?</div><div class=\"q-ar\">أي جملة هي المبني للمجهول الصحيح لـ <span class=\"en\">Somebody has stolen my wallet</span>؟</div>", "o": ["My wallet was stolen by has.", "My wallet is steal.", "My wallet has stolen.", "My wallet has been stolen."], "a": 3, "ex": ["<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Wrong: no passive form.</div><div class=\"ex-ar\">غلط: مفيش صيغة مبني للمجهول.</div>", "<div class=\"ex-en\">Right: be in the same tense (present perfect) plus the past participle.</div><div class=\"ex-ar\">صح: <span class=\"en\">be</span> بنفس الزمن + التصريف الثالث.</div>"], "l": "tefl-12"}, {"id": "tefl-m02-practice-A:10", "type": "mc4", "q": "<div class=\"q-hard\">Which part of speech is 'bravery' in 'His incredible bravery was rewarded'?</div><div class=\"q-simple\">What part of speech is 'bravery'?</div><div class=\"q-ar\">إيه نوع الكلمة <span class=\"en\">bravery</span> في <span class=\"en\">His incredible bravery was rewarded</span>؟</div>", "o": ["An adverb", "A verb", "An adjective", "A noun (abstract)"], "a": 3, "ex": ["<div class=\"ex-en\">Wrong: it does not describe a verb.</div><div class=\"ex-ar\">غلط: مش بتصف فعل.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Wrong: 'incredible' is the adjective.</div><div class=\"ex-ar\">غلط: <span class=\"en\">incredible</span> هي الصفة.</div>", "<div class=\"ex-en\">Right: it names a concept.</div><div class=\"ex-ar\">صح: بتسمّي مفهوم.</div>"], "l": "tefl-13"}, {"id": "tefl-m02-practice-A:11", "type": "tf", "q": "<div class=\"q-hard\">An adverb can modify a noun.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">الظرف ممكن يعدّل اسم.</div>", "o": ["True", "False"], "a": 1, "ex": ["<div class=\"ex-en\">Wrong: the statement is false. Adjectives modify nouns. Adverbs modify verbs, adjectives or other adverbs.</div><div class=\"ex-ar\">غلط: العبارة غلط. الصفات بتعدّل الأسماء، والظروف بتعدّل الأفعال والصفات والظروف التانية.</div>", "<div class=\"ex-en\">Adjectives modify nouns. Adverbs modify verbs, adjectives or other adverbs.</div><div class=\"ex-ar\">الصفات بتعدّل الأسماء، والظروف بتعدّل الأفعال والصفات والظروف التانية.</div>"], "l": "tefl-13"}, {"id": "tefl-m02-practice-A:12", "type": "mc4", "q": "<div class=\"q-hard\">Which word is NOT an adjective among the words built from 'satisfy'?</div><div class=\"q-simple\">Which is not an adjective?</div><div class=\"q-ar\">أي كلمة مش صفة من الكلمات المشتقة من <span class=\"en\">satisfy</span>؟</div>", "o": ["satisfying", "satisfactory", "satisfactorily", "satisfied"], "a": 2, "ex": ["<div class=\"ex-en\">Wrong: an adjective.</div><div class=\"ex-ar\">غلط: صفة.</div>", "<div class=\"ex-en\">Wrong: an adjective.</div><div class=\"ex-ar\">غلط: صفة.</div>", "<div class=\"ex-en\">Right: it is an adverb.</div><div class=\"ex-ar\">صح: ظرف.</div>", "<div class=\"ex-en\">Wrong: an adjective.</div><div class=\"ex-ar\">غلط: صفة.</div>"], "l": "tefl-13"}, {"id": "tefl-m02-practice-A:13", "type": "mc4", "q": "<div class=\"q-hard\">How many phonemes are there in standard modern English?</div><div class=\"q-simple\">How many phonemes does English have?</div><div class=\"q-ar\">كام فونيم في الإنجليزي الحديث القياسي؟</div>", "o": ["44", "52", "12", "26"], "a": 0, "ex": ["<div class=\"ex-en\">Right: fairly evenly divided between vowels and consonants.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Wrong: 26 is the number of letters.</div><div class=\"ex-ar\">غلط: 26 عدد الحروف.</div>"], "l": "tefl-14"}, {"id": "tefl-m02-practice-A:14", "type": "mc4", "q": "<div class=\"q-hard\">How can you find the number of clauses in a sentence quickly?</div><div class=\"q-simple\">How do you count clauses?</div><div class=\"q-ar\">إزاي تعرف عدد الجمل الفرعية والرئيسية بسرعة؟</div>", "o": ["Count the main verbs: each main verb is one clause", "Count the capital letters", "Count the commas", "Count the nouns"], "a": 0, "ex": ["<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>", "<div class=\"ex-en\">Wrong.</div><div class=\"ex-ar\">غلط.</div>"], "l": "tefl-14"}, {"id": "tefl-m02-practice-A:15", "type": "msel", "q": "<div class=\"q-hard\">Which of the following are verb phrases? Tick all that apply.</div><div class=\"q-simple\">Which are verb phrases? Tick all that apply.</div><div class=\"q-ar\">أي من دي عبارات فعلية؟ اختار كل الإجابات الصح.</div><div class=\"q-note\">Tick ALL that apply. / اختار كل الإجابات الصح.</div>", "o": ["may have been planning", "can see", "would have sent", "a pile of books"], "a": [0, 1, 2], "ex": ["<div class=\"ex-en\">Right: the main verb is last.</div><div class=\"ex-ar\">صح: الفعل الرئيسي في الآخر.</div>", "<div class=\"ex-en\">Right: auxiliary + main verb.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Right.</div><div class=\"ex-ar\">صح.</div>", "<div class=\"ex-en\">Wrong: this is a noun phrase.</div><div class=\"ex-ar\">غلط: دي عبارة اسمية.</div>"], "l": "tefl-14"}, {"id": "tefl-m02-practice-A:16", "type": "mc4", "q": "<div class=\"q-hard\">Which sentence is compound?</div><div class=\"q-simple\">Which sentence is compound?</div><div class=\"q-ar\">أي جملة مركبة (compound)؟</div>", "o": ["I do not like eating strawberries but I love eating carrots.", "Made in France.", "When the noisy vehicle passed, the mighty lion roared.", "The dog barked."], "a": 0, "ex": ["<div class=\"ex-en\">Right: two main clauses joined by 'but'.</div><div class=\"ex-ar\">صح: جملتين رئيسيتين بـ <span class=\"en\">but</span>.</div>", "<div class=\"ex-en\">Wrong: not a sentence.</div><div class=\"ex-ar\">غلط: مش جملة.</div>", "<div class=\"ex-en\">Wrong: complex.</div><div class=\"ex-ar\">غلط: معقدة.</div>", "<div class=\"ex-en\">Wrong: simple.</div><div class=\"ex-ar\">غلط: بسيطة.</div>"], "l": "tefl-15"}, {"id": "tefl-m02-practice-A:17", "type": "tf", "q": "<div class=\"q-hard\">An independent clause is another name for the main clause.</div><div class=\"q-simple\">True or false?</div><div class=\"q-ar\">الـ <span class=\"en\">independent clause</span> اسم تاني للجملة الرئيسية.</div>", "o": ["True", "False"], "a": 0, "ex": ["<div class=\"ex-en\">The dependent clause is the subordinate one.</div><div class=\"ex-ar\">التابعة هي الفرعية.</div>", "<div class=\"ex-en\">Wrong: the statement is true.</div><div class=\"ex-ar\">غلط: العبارة صح.</div>"], "l": "tefl-15"}]}]};